<div class="head"><div><h1><?= icon('chart') ?> Activity Log</h1><p class="muted">Audit trail of important actions.</p></div></div>
<form method="get" class="filter"><input type="hidden" name="r" value="reports/activity"><select name="action" aria-label="Action"><option value="">All actions</option><?php foreach ($actions as $x): ?><option <?= $a === $x ? 'selected' : '' ?>><?= e($x) ?></option><?php endforeach; ?></select><button class="btn sm">Filter</button></form>
<div class="panel"><div class="tw"><table><tr><th>Time</th><th>User</th><th>Action</th><th>Details</th><th>IP</th></tr><?php foreach ($rows as $r): ?><tr><td><?= e($r['created_at']) ?></td><td><?= e($r['username'] ?? '—') ?></td><td><?= e($r['action']) ?></td><td><?= e($r['details']) ?></td><td><?= e($r['ip_address']) ?></td></tr><?php endforeach; ?></table></div></div>
